# Print orbit partition of Z_l for the multiplier group generated by argv[2:], plus optional shift c (affine x->g*x+c for first gen)
import sys
from math import gcd
l = int(sys.argv[1]); gens = [int(x) for x in sys.argv[2:]]
H = {1}
while True:
    T = H | {(a*g) % l for a in H for g in gens}
    if T == H: break
    H = T
seen = set(); orbs = []
for j in range(l):
    if j in seen: continue
    o = sorted({(j*x) % l for x in H}); seen |= set(o); orbs.append(o)
print(l, len(orbs))
for o in orbs: print(len(o), *o)
